/**
 * Picks one value from a few options that are all visible (`design/components/radio.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/radio.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import * as zag from '@zag-js/radio-group'
import { normalizeProps } from '@zag-js/solid'

import {
  Each,
  agentMember,
  claimSlot,
  createDerived,
  elementRef,
  roveRadio,
  useDirection,
  useMachine,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/radio-group.module.css'

export type RadioOrientation = NonNullable<RadioGroupProps['orientation']>

export interface RadioOption {
  value: string
  label: string
  disabled?: boolean
}

export interface RadioGroupProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField, because the group's question is the field's label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  defaultValue?: string
  disabled?: boolean
  id?: string
  invalid?: boolean
  name?: string
  onChange?: (value: string) => void
  options: RadioOption[]
  /**
   * Horizontal is for three short labels at most. Guidance, not enforcement.
   */
  orientation?: 'horizontal' | 'vertical'
  value?: string
}

/** Picks one value from a few options that are all visible. */
export default function RadioGroup(given: RadioGroupProps): JSX.Element {
  const props = mergeProps(
    { orientation: 'vertical', invalid: false, disabled: false } as Defaults<
      RadioGroupProps,
      'orientation' | 'invalid' | 'disabled'
    >,
    claimSlot(given, 'group'),
  )
  const uid = createUniqueId()
  const group = elementRef<HTMLElement>()
  const documentDirection = useDirection()
  const service = useMachine(
    zag.machine,
    () =>
      ({
        id: uid,
        dir: documentDirection(),
        value: props.value,
        defaultValue: props.defaultValue,
        disabled: props.disabled,
        name: props.name,
        orientation: props.orientation,
        onValueChange: (details) => {
          props.onChange?.(details.value ?? '')
        },
      }) as Partial<zag.Props>,
  )
  const api = createDerived(() => zag.connect(service, normalizeProps))
  const stop = createDerived(
    () =>
      api.value.value ??
      props.options.find((option) => !(props.disabled || option.disabled === true))?.value,
  )
  let release1: (() => void) | undefined
  const effect1 = () => {
    release1?.()
    const ran = agentMember({
      member: 'RadioGroup',
      element: () => group.value,
      state: () => ({
        value: api.value.value ?? null,
        options: props.options.map((option) => ({
          id: option.value,
          label: option.label,
          ...(option.disabled === true ? { disabled: true } : {}),
        })),
        disabled: props.disabled,
        invalid: props.invalid,
      }),
      actions: {
        choose: {
          argument: 'id',
          run: (value) => value !== api.value.value && api.value.setValue(value),
        },
      },
    })
    release1 = () => {
      ran()
    }
  }
  onMount(effect1)
  onCleanup(() => release1?.())
  return (
    <>
      {/* root */}
      <div
        class={styles.group}
        role="radiogroup"
        id={props.id}
        aria-label={props['aria-label']}
        aria-labelledby={props['aria-labelledby']}
        aria-describedby={props['aria-describedby']}
        aria-required={props['aria-required']}
        aria-invalid={props.invalid ? true : undefined}
        data-orientation={props.orientation}
        data-disabled={props.disabled ? '' : undefined}
        data-invalid={props.invalid ? '' : undefined}
        data-required={props['aria-required'] ? '' : undefined}
        data-member="radio-group"
        ref={group.attach}
      >
        <Each of={props.options} by={(option) => option.value} renew>
          {(option) => (
            <label class={styles.row}>
              {/* radio */}
              <button
                class={styles.circle}
                type="button"
                role="radio"
                value={option.value}
                aria-checked={api.value.value === option.value}
                disabled={props.disabled || option.disabled === true}
                tabindex={option.value === stop.value ? 0 : -1}
                data-state={api.value.value === option.value ? 'checked' : 'unchecked'}
                data-disabled={props.disabled || option.disabled === true ? '' : undefined}
                onclick={() => api.value.setValue(option.value)}
                onkeydown={($event: KeyboardEvent) =>
                  $event.key === 'Enter'
                    ? $event.preventDefault()
                    : roveRadio($event, (next) => api.value.setValue(next))
                }
              >
                {api.value.value === option.value ? (
                  <span class={styles.dot} data-state="checked" />
                ) : null}
              </button>
              <span class={styles.label}>{option.label}</span>
            </label>
          )}
        </Each>
      </div>
      {props.name !== undefined ? (
        <input
          type="hidden"
          name={props.name}
          value={api.value.value ?? ''}
          disabled={props.disabled}
        />
      ) : null}
    </>
  )
}

RadioGroup.controlKind = 'group'
